package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden holds a diagram of the kindergarten garden and the list of
// children (in alphabetical order) assigned to the cups.
type Garden struct {
	rows     [2]string
	children []string
}

var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// NewGarden parses the diagram (two rows, each prefixed by '\n') and
// assigns the cups to children alphabetically.
func NewGarden(diagram string, children []string) (*Garden, error) {
	rows := strings.Split(strings.TrimPrefix(diagram, "\n"), "\n")
	if len(rows) != 2 {
		return nil, errors.New("diagram must have exactly two rows")
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[0])%2 != 0 {
		return nil, errors.New("diagram must have an even number of cups")
	}
	for _, r := range rows[0] + rows[1] {
		if _, ok := plantNames[r]; !ok {
			return nil, fmt.Errorf("invalid cup code %q", r)
		}
	}
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	for i := 1; i < len(sorted); i++ {
		if sorted[i] == sorted[i-1] {
			return nil, fmt.Errorf("duplicate name %q", sorted[i])
		}
	}
	if len(sorted) != len(rows[0])/2 {
		return nil, errors.New("number of children does not match number of cups")
	}
	return &Garden{rows: [2]string{rows[0], rows[1]}, children: sorted}, nil
}

// Plants returns the four plants assigned to the named child, or ok = false
// if the child is not in this garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	i, ok := sort.Search(len(g.children), func(i int) bool {
		return g.children[i] >= child
	}), true
	...
}
