package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden holds a diagram of the kindergarten garden and the list of
// children, in alphabetical order, assigned to the cups.
type Garden struct {
	rows     [2]string
	children []string
}

var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// NewGarden parses the diagram and assigns the cups to the children.
//
// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//     diagram := `
//     VVCCGG
//     VVCCGG`
func NewGarden(diagram string, children []string) (*Garden, error) {
	rows := strings.Split(diagram, "\n")
	if len(rows) != 3 || rows[0] != "" {
		return nil, errors.New("diagram must consist of two rows, each prefixed by a newline")
	}
	if len(rows[1]) != len(rows[2]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[1])%2 != 0 {
		return nil, errors.New("diagram must have an even number of cups")
	}
	for _, r := range rows[1] + rows[2] {
		if _, ok := plantNames[r]; !ok {
			return nil, fmt.Errorf("invalid cup code %q", r)
		}
	}

	// Sort a copy so the caller's slice is left untouched.
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	for i := 1; i < len(sorted); i++ {
		if sorted[i] == sorted[i-1] {
			return nil, fmt.Errorf("duplicate name %q", sorted[i])
		}
	}
	if len(sorted) != len(rows[1])/2 {
		return nil, errors.New("number of children does not match number of cups")
	}

	return &Garden{rows: [2]string{rows[1], rows[2]}, children: sorted}, nil
}

// Plants returns the four plants assigned to the named child, two from the
// row nearest the windows and two from the other row, or ok = false if the
// child is not in this garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	i := sort.SearchStrings(g.children, child)
	if i == len(g.children) || g.children[i] != child {
		return nil, false
	}
	plants := make([]string, 4)
	plants[0] = plantNames[rune(g.rows[0][2*i])]
	plants[1] = plantNames[rune(g.rows[0][2*i+1])]
	plants[2] = plantNames[rune(g.rows[1][2*i])]
	plants[3] = plantNames[rune(g.rows[1][2*i+1])]
	return plants, true
}
